"use client";

import { type DailyTask, useDailyTaskListContext } from "./daily-task-list-state";
import { type ReactNode } from "react";
import { Checkbox } from "@base-ui/react/checkbox";
import { cn } from "@/lib/utils";
import { useSortableList } from "@/components/ui/sortable-list";
import { ContextMenu, ContextMenuTarget, ContextMenuButton, ContextMenuContent, ContextMenuItem, ContextMenuSeparator } from "@/components/ui/context-menu";

export type RowOptions = {
  /** Extra content under each title, such as a time or tag. */
  renderMeta?: (task: DailyTask) => ReactNode;
  /** Extra menu items for each task, rendered after the built-in actions. */
  renderActions?: (task: DailyTask) => ReactNode;
  classNames?: { item?: string; row?: string; checkbox?: string; title?: string; menu?: string; menuItem?: string; menuHighlight?: string };
};

/** How long the strike line takes to cross a title before the task moves to Completed. */
export const STRIKE_MS = 320;

export function TaskCheckbox({ task, className }: { task: DailyTask; className?: string }) {
  const { toggle, busy, striking, disabled, animated, messages } = useDailyTaskListContext("DailyTaskList");
  return (
    <Checkbox.Root
      // Shown as checked while the strike plays; it reverts if the app's save fails.
      checked={task.done || striking.has(task.id)}
      onCheckedChange={() => toggle(task)}
      // A save in flight blocks another click in toggle(), without dimming the row before it moves.
      disabled={disabled}
      aria-label={task.done ? `${messages.reopen} ${task.title}` : task.title}
      aria-busy={busy.has(task.id) || undefined}
      className={cn(
        "group grid size-5 shrink-0 place-items-center rounded-[5px] border border-input bg-background shadow-xs outline-none focus-visible:ring-1 focus-visible:ring-ring data-[checked]:border-primary data-[checked]:bg-primary data-[checked]:text-primary-foreground data-[disabled]:opacity-50",
        className,
      )}
    >
      <Checkbox.Indicator keepMounted>
        <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" strokeLinejoin="round" className="size-3.5">
          {/* The tick draws itself in when checked. */}
          <path
            d="M3.5 8.5l3 3 6-7"
            pathLength={1}
            className={cn(
              "[stroke-dasharray:1] [stroke-dashoffset:1] group-data-[checked]:[stroke-dashoffset:0]",
              animated && "transition-[stroke-dashoffset] duration-200 ease-out motion-reduce:transition-none",
            )}
          />
        </svg>
      </Checkbox.Indicator>
    </Checkbox.Root>
  );
}

export function TaskMenu({ task, index, count, options, children }: { task: DailyTask; index: number; count: number; options: RowOptions; children: ReactNode }) {
  const { messages, disabled, busy, rename, reorder, remove, toggle, setRenamingId, renamingId, animated, portal } = useDailyTaskListContext("DailyTaskList");
  const { move } = useSortableList<DailyTask>();
  const blocked = disabled || busy.has(task.id);
  const item = options.classNames?.menuItem;
  return (
    <ContextMenu disabled={blocked || renamingId === task.id} motion={animated}>
      <ContextMenuTarget className={cn("flex min-w-0 flex-1 items-center gap-2.5", options.classNames?.row)}>
        {children}
        {/* Locked while its save is in flight, without dimming the row before it moves. */}
        <ContextMenuButton aria-label={messages.actions(task.title)} className={cn(busy.has(task.id) && !disabled && "disabled:opacity-100")} />
      </ContextMenuTarget>
      <ContextMenuContent container={portal} className={options.classNames?.menu} highlightClassName={options.classNames?.menuHighlight}>
        {task.done ? (
          <ContextMenuItem className={item} onClick={() => toggle(task)}>
            {messages.reopen}
          </ContextMenuItem>
        ) : (
          rename && (
            <ContextMenuItem className={item} onClick={() => setRenamingId(task.id)}>
              {messages.rename}
            </ContextMenuItem>
          )
        )}
        {reorder && (
          <>
            <ContextMenuItem className={item} disabled={index === 0} onClick={() => move(task.id, index - 1)}>
              {messages.moveUp}
            </ContextMenuItem>
            <ContextMenuItem className={item} disabled={index === count - 1} onClick={() => move(task.id, index + 1)}>
              {messages.moveDown}
            </ContextMenuItem>
          </>
        )}
        {options.renderActions?.(task)}
        <ContextMenuSeparator />
        <ContextMenuItem className={item} variant="destructive" onClick={() => remove(task)}>
          {messages.delete}
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef, useState, useRef, useId } from "react";
import { useDailyTaskListContext } from "./daily-task-list-state";
import { cn } from "@/lib/utils";

export type DailyTaskListHeaderProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The day, for example “Today” or “Monday 2 November”. */
  label: ReactNode;
  /** Extra content beside the label, such as a date picker you provide. */
  children?: ReactNode;
};

/** The day label and a progress summary of completed tasks. */
export const DailyTaskListHeader = forwardRef<HTMLDivElement, DailyTaskListHeaderProps>(function DailyTaskListHeader(
  { label, className, children, ...props },
  ref,
) {
  const { active, completed, messages, animated } = useDailyTaskListContext("DailyTaskListHeader");
  const total = active.length + completed.length;
  const done = completed.length;
  return (
    <div ref={ref} className={cn("flex flex-col gap-2", className)} {...props}>
      <div className="flex items-baseline justify-between gap-3">
        <h3 className="text-base font-semibold">{label}</h3>
        {children}
        {total > 0 && <p className="shrink-0 text-xs text-muted-foreground">{messages.progress(done, total)}</p>}
      </div>
      {total > 0 && (
        <div
          role="progressbar"
          aria-label={messages.progress(done, total)}
          aria-valuemin={0}
          aria-valuemax={total}
          aria-valuenow={done}
          className="h-1 overflow-hidden rounded-full bg-muted"
        >
          <div className={cn("h-full rounded-full bg-primary", animated && "transition-[width] duration-500 ease-out motion-reduce:transition-none")} style={{ width: `${(done / total) * 100}%` }} />
        </div>
      )}
    </div>
  );
});

/** Quick capture. The text stays until your app confirms the new task; a rejected title or failed save keeps it with a message. */
export const DailyTaskListCapture = forwardRef<HTMLFormElement, Omit<ComponentPropsWithoutRef<"form">, "children">>(function DailyTaskListCapture(
  { className, onSubmit, ...props },
  ref,
) {
  const { create, validate, messages, disabled } = useDailyTaskListContext("DailyTaskListCapture");
  const [text, setText] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const errorId = useId();
  if (!create) return null;

  const submit = () => {
    const invalid = validate(text);
    if (invalid) return setError(invalid);
    setError(null);
    const result = create(text.trim());
    const added = () => {
      setText("");
      input.current?.focus();
    };
    if (!(result instanceof Promise)) return added();
    setPending(true);
    result.then(
      () => {
        setPending(false);
        added();
      },
      () => {
        setPending(false);
        setError(messages.failed("create", text.trim()));
      },
    );
  };

  return (
    <form
      ref={ref}
      className={cn("flex flex-col gap-1.5", className)}
      onSubmit={(event) => {
        onSubmit?.(event);
        event.preventDefault();
        if (!pending && !disabled) submit();
      }}
      {...props}
    >
      <div className="flex gap-2">
        <input
          ref={input}
          value={text}
          onChange={(event) => {
            setText(event.target.value);
            if (error) setError(null);
          }}
          placeholder={messages.placeholder}
          aria-label={messages.placeholder}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? errorId : undefined}
          aria-busy={pending || undefined}
          disabled={disabled}
          className="h-9 min-w-0 flex-1 rounded-md border border-input bg-transparent px-3 text-base shadow-xs outline-none placeholder:text-muted-foreground focus-visible:border-ring disabled:opacity-50 aria-invalid:border-destructive sm:text-sm"
        />
        <button
          type="submit"
          aria-disabled={pending || disabled || undefined}
          className="h-9 shrink-0 rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground shadow-xs transition-opacity hover:bg-primary/90 focus-visible:outline-none focus-visible:bg-primary/90 aria-disabled:opacity-50"
        >
          {messages.add}
        </button>
      </div>
      {error && (
        <p id={errorId} role="alert" className="flex items-center gap-2 px-1 text-xs text-destructive">
          {error}
          {error !== validate(text) && (
            <button type="button" onClick={submit} className="font-medium underline underline-offset-4">
              {messages.retry}
            </button>
          )}
        </p>
      )}
    </form>
  );
});

"use client";

import { forwardRef, type ComponentPropsWithoutRef } from "react";
import { useDailyTaskListContext } from "./daily-task-list-state";
import { cn } from "@/lib/utils";

/** Shown when there are no active tasks: “Nothing planned yet”, or “All done” once everything is complete. Children replace the message. */
export const DailyTaskListEmpty = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function DailyTaskListEmpty(
  { className, children, ...props },
  ref,
) {
  const { active, completed, messages } = useDailyTaskListContext("DailyTaskListEmpty");
  if (active.length > 0) return null;
  return (
    <div ref={ref} className={cn("rounded-md border border-dashed border-border p-6 text-center text-muted-foreground", className)} {...props}>
      {children ?? (completed.length > 0 ? messages.allDone : messages.empty)}
    </div>
  );
});

/** Undo after a delete, and Retry after a failed action. Your app's data is never shown as changed when a save failed. */
export const DailyTaskListFeedback = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<"div">, "children">>(function DailyTaskListFeedback(
  { className, ...props },
  ref,
) {
  const { failure, deleted, messages, restore, dismiss, busy } = useDailyTaskListContext("DailyTaskListFeedback");
  const restoring = deleted ? busy.has(deleted.id) : false;
  return (
    <div ref={ref} role="status" aria-live="polite" className={cn("empty:hidden", className)} {...props}>
      {(failure || deleted) && (
        <div
          className={cn(
            "flex items-center justify-between gap-3 rounded-md border px-3 py-2",
            failure
              ? "border-[color-mix(in_oklab,var(--destructive)_30%,var(--background))] bg-[color-mix(in_oklab,var(--destructive)_12%,var(--background))] text-destructive"
              : "border-border bg-muted text-foreground",
          )}
        >
          <span>{failure ? messages.failed(failure.action, failure.title) : deleted && messages.deleted(deleted.title)}</span>
          <span className="flex shrink-0 items-center gap-3">
            {failure ? (
              <button type="button" onClick={failure.retry} className="font-medium underline underline-offset-4">
                {messages.retry}
              </button>
            ) : (
              <button type="button" onClick={restore} aria-disabled={restoring || undefined} className="font-medium underline underline-offset-4 aria-disabled:opacity-50">
                {messages.undo}
              </button>
            )}
            <button type="button" onClick={dismiss} aria-label={messages.dismiss} className="text-muted-foreground hover:text-foreground">
              <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" className="size-3.5">
                <path d="M4 4l8 8M12 4l-8 8" />
              </svg>
            </button>
          </span>
        </div>
      )}
    </div>
  );
});

/** State of the nearest DailyTaskList, for building your own parts. */
export function useDailyTaskList() {
  const { active, completed, busy, failure, deleted, toggle, remove, restore, dismiss } = useDailyTaskListContext("useDailyTaskList");
  return { active, completed, busy, failure, deleted, toggle, remove, restore, dismiss };
}

"use client";

import { type DailyTask, type DailyTaskListProps, defaultMessages, type Failure, type DailyTaskAction, type Result, type ContextValue, Context } from "./daily-task-list-state";
import { type ForwardedRef, useState, forwardRef } from "react";
import { STRIKE_MS } from "./daily-task-list-actions";
import { cn } from "@/lib/utils";
import { LayoutGroup } from "motion/react";

export function DailyTaskListRoot<T extends DailyTask>(
  {
    tasks,
    onCreate,
    onRename,
    onToggle,
    onReorder,
    onDelete,
    onRestore,
    validateTitle,
    disabled = false,
    motion = true,
    messages: overrides,
    portalContainer,
    className,
    children,
    ...props
  }: DailyTaskListProps<T>,
  ref: ForwardedRef<HTMLDivElement>,
) {
  const messages = { ...defaultMessages, ...overrides };
  const [busy, setBusy] = useState<Set<string>>(() => new Set());
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [deleted, setDeleted] = useState<DailyTask | null>(null);
  const [failure, setFailure] = useState<Failure | null>(null);
  const [striking, setStriking] = useState<Set<string>>(() => new Set());

  const mark = (id: string, on: boolean) =>
    setBusy((previous) => {
      const next = new Set(previous);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });

  const strike = (id: string, on: boolean) =>
    setStriking((previous) => {
      const next = new Set(previous);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });

  /** Runs a host callback for one task, marking it busy while a returned promise is pending. */
  const run = (task: DailyTask, action: DailyTaskAction, call: () => Result, done?: () => void, failed?: () => void) => {
    setFailure(null);
    const retry = () => run(task, action, call, done, failed);
    const result = call();
    if (!(result instanceof Promise)) return done?.();
    mark(task.id, true);
    result.then(
      () => {
        mark(task.id, false);
        done?.();
      },
      () => {
        mark(task.id, false);
        failed?.();
        setFailure({ action, title: task.title, retry });
      },
    );
  };

  /** Completing first strikes the title, then saves; a failed save retracts the strike. */
  const toggle = (task: DailyTask) => {
    if (!onToggle || striking.has(task.id) || busy.has(task.id)) return;
    const save = () =>
      run(task, task.done ? "reopen" : "complete", () => onToggle(task as T, !task.done), () => strike(task.id, false), () => strike(task.id, false));
    if (task.done || !motion) return save();
    strike(task.id, true);
    window.setTimeout(save, STRIKE_MS);
  };

  const value: ContextValue = {
    active: tasks.filter((task) => !task.done),
    completed: tasks.filter((task) => task.done),
    messages,
    disabled,
    animated: motion,
    portal: portalContainer,
    busy,
    striking,
    renamingId,
    setRenamingId,
    deleted,
    failure,
    validate: (title) => (validateTitle ? (validateTitle(title) ?? null) : title.trim() ? null : messages.required),
    create: onCreate,
    rename: onRename as ContextValue["rename"],
    reorder: onReorder as ContextValue["reorder"],
    toggle,
    remove: (task) =>
      onDelete &&
      run(task, "delete", () => onDelete(task as T), () => {
        setRenamingId(null);
        setDeleted(task);
      }),
    restore: () => deleted && onRestore && run(deleted, "restore", () => onRestore(deleted as T), () => setDeleted(null)),
    dismiss: () => {
      setFailure(null);
      setDeleted(null);
    },
  };

  return (
    <Context.Provider value={value}>
      <div ref={ref} data-disabled={disabled ? "" : undefined} className={cn("flex flex-col gap-4 text-sm", className)} {...props}>
        {/* One layout group, so a completed task slides into Completed and the rows around it close up together. */}
        <LayoutGroup>{children}</LayoutGroup>
      </div>
    </Context.Provider>
  );
}

/** A day's tasks with capture, editing, ordering, completion and recovery wired together. Compose the parts you need. */
export const DailyTaskList = forwardRef(DailyTaskListRoot) as <T extends DailyTask>(
  props: DailyTaskListProps<T> & { ref?: ForwardedRef<HTMLDivElement> },
) => ReturnType<typeof DailyTaskListRoot>;

"use client";

import { type DailyTask, useDailyTaskListContext } from "./daily-task-list-state";
import { type RowOptions, TaskMenu, TaskCheckbox } from "./daily-task-list-actions";
import { SortableList, SortableListContent, SortableListItem, SortableListHandle, SortableListError } from "@/components/ui/sortable-list";
import { cn } from "@/lib/utils";
import { TaskTitle } from "./daily-task-list-title";
import { type ComponentPropsWithoutRef, forwardRef, useState, useId } from "react";

/**
 * The rows of one section. Active and completed tasks share this exact row: handle,
 * checkbox, title with optional meta and the actions button. Rows carry a layout id so
 * a completed task slides from one section into the other.
 */
export function TaskRows({ section, tasks, options }: { section: "active" | "completed"; tasks: DailyTask[]; options: RowOptions }) {
  const { reorder, disabled, busy, striking, animated } = useDailyTaskListContext("DailyTaskList");
  return (
    <SortableList
      items={tasks}
      getId={(task) => task.id}
      getLabel={(task) => task.title}
      isLocked={(task) => busy.has(task.id) || striking.has(task.id)}
      onOrderChange={reorder && ((next, move) => reorder(next, move, section))}
      disabled={disabled || !reorder}
      motion={animated}
      className="gap-2"
    >
      <SortableListContent>
        {(task: DailyTask, index: number) => (
          <SortableListItem
            {...(animated ? { layoutId: `daily-task-${task.id}`, transition: { layout: { duration: 0.45, ease: [0.22, 1, 0.36, 1] } } } : {})}
            className={cn("gap-1 py-2 pl-1 pr-1.5", options.classNames?.item)}
          >
            <SortableListHandle className={cn((busy.has(task.id) || striking.has(task.id)) && !disabled && "aria-disabled:opacity-100")} />
            <TaskMenu task={task} index={index} count={tasks.length} options={options}>
              <TaskCheckbox task={task} className={options.classNames?.checkbox} />
              <span className="flex min-w-0 flex-1 flex-col">
                <TaskTitle task={task} options={options} />
                {options.renderMeta && <span className="truncate px-1 text-xs text-muted-foreground">{options.renderMeta(task)}</span>}
              </span>
            </TaskMenu>
          </SortableListItem>
        )}
      </SortableListContent>
      <SortableListError />
    </SortableList>
  );
}

export type DailyTaskListActiveProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & RowOptions;

/** Active tasks: complete, rename, reorder by handle or menu, and delete. */
export const DailyTaskListActive = forwardRef<HTMLDivElement, DailyTaskListActiveProps>(function DailyTaskListActive(
  { renderMeta, renderActions, classNames, className, ...props },
  ref,
) {
  const { active } = useDailyTaskListContext("DailyTaskListActive");
  if (active.length === 0) return null;
  return (
    <div ref={ref} className={className} {...props}>
      <TaskRows section="active" tasks={active} options={{ renderMeta, renderActions, classNames }} />
    </div>
  );
});

export type DailyTaskListCompletedProps = Omit<ComponentPropsWithoutRef<"section">, "children"> &
  RowOptions & {
    /** Start collapsed. Defaults to open. */
    defaultCollapsed?: boolean;
  };

/** Completed tasks in their own collapsible section, with the same rows: reorder among themselves, reopen or delete. */
export const DailyTaskListCompleted = forwardRef<HTMLElement, DailyTaskListCompletedProps>(function DailyTaskListCompleted(
  { renderMeta, renderActions, classNames, defaultCollapsed = false, className, ...props },
  ref,
) {
  const { completed, messages, animated } = useDailyTaskListContext("DailyTaskListCompleted");
  const [open, setOpen] = useState(!defaultCollapsed);
  const regionId = useId();
  if (completed.length === 0) return null;
  return (
    <section ref={ref} className={cn("flex flex-col gap-2", className)} {...props}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={regionId}
        onClick={() => setOpen(!open)}
        className="flex items-center gap-1.5 self-start rounded-md px-1 py-1 text-xs font-medium text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:bg-foreground/10 focus-visible:text-foreground"
      >
        <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" className={cn("size-3.5", open && "rotate-90", animated && "transition-transform duration-200 motion-reduce:transition-none")}>
          <path d="M6 4l4 4-4 4" />
        </svg>
        {messages.completed(completed.length)}
      </button>
      <div id={regionId} hidden={!open}>
        <TaskRows section="completed" tasks={completed} options={{ renderMeta, renderActions, classNames }} />
      </div>
    </section>
  );
});

"use client";

import { createContext, useContext, type ComponentPropsWithoutRef, type ReactNode } from "react";

/** The fields the block reads. Your task type can carry anything else. */
export type DailyTask = { id: string; title: string; done: boolean };

export type Result = void | Promise<unknown>;

export type DailyTaskAction = "create" | "complete" | "reopen" | "delete" | "restore";

/** Labels and announcements. Replace any of them, for example to translate. */
export type DailyTaskListMessages = {
  placeholder: string;
  add: string;
  /** Accessible name of each task's title field. */
  titleLabel: string;
  required: string;
  progress: (done: number, total: number) => string;
  completed: (count: number) => string;
  empty: string;
  allDone: string;
  rename: string;
  moveUp: string;
  moveDown: string;
  delete: string;
  reopen: string;
  actions: (title: string) => string;
  deleted: (title: string) => string;
  undo: string;
  failed: (action: DailyTaskAction, title: string) => string;
  retry: string;
  dismiss: string;
};

export const defaultMessages: DailyTaskListMessages = {
  placeholder: "Add a task",
  add: "Add",
  titleLabel: "Task title",
  required: "Enter a task name.",
  progress: (done, total) => `${done} of ${total} done`,
  completed: (count) => `Completed (${count})`,
  empty: "Nothing planned yet.",
  allDone: "All done for today.",
  rename: "Rename",
  moveUp: "Move up",
  moveDown: "Move down",
  delete: "Delete",
  reopen: "Reopen",
  actions: (title) => `Actions for ${title}`,
  deleted: (title) => `Deleted “${title}”.`,
  undo: "Undo",
  failed: (action, title) =>
    ({
      create: `Couldn't add “${title}”.`,
      complete: `Couldn't complete “${title}”.`,
      reopen: `Couldn't reopen “${title}”.`,
      delete: `Couldn't delete “${title}”.`,
      restore: `Couldn't restore “${title}”.`,
    })[action],
  retry: "Retry",
  dismiss: "Dismiss",
};

export type Failure = { action: DailyTaskAction; title: string; retry: () => void };

export type ContextValue = {
  active: DailyTask[];
  completed: DailyTask[];
  messages: DailyTaskListMessages;
  disabled: boolean;
  animated: boolean;
  portal: HTMLElement | null | undefined;
  busy: Set<string>;
  /** Tasks whose strike line is playing before their completion is saved. */
  striking: Set<string>;
  renamingId: string | null;
  setRenamingId: (id: string | null) => void;
  deleted: DailyTask | null;
  failure: Failure | null;
  validate: (title: string) => string | null;
  create?: (title: string) => Result;
  rename?: (task: DailyTask, title: string) => Result;
  reorder?: (ordered: DailyTask[], move: { item: DailyTask; from: number; to: number }, section: "active" | "completed") => Result;
  toggle: (task: DailyTask) => void;
  remove: (task: DailyTask) => void;
  restore: () => void;
  dismiss: () => void;
};

export const Context = createContext<ContextValue | null>(null);

export function useDailyTaskListContext(part: string) {
  const context = useContext(Context);
  if (!context) throw new Error(`<${part}> must be used inside <DailyTaskList>.`);
  return context;
}

export type DailyTaskListProps<T extends DailyTask> = Omit<ComponentPropsWithoutRef<"div">, "children" | "onToggle"> & {
  /** All of the day's tasks in your order. Active and completed tasks are shown in separate sections. */
  tasks: T[];
  /** Each callback may return a promise: the block shows it as saving, and a rejection keeps your data unchanged with Retry. */
  onCreate?: (title: string) => Result;
  onRename?: (task: T, title: string) => Result;
  onToggle?: (task: T, done: boolean) => Result;
  /** Called once per completed move with the new order of that section's tasks. Active and completed tasks are ordered separately. */
  onReorder?: (ordered: T[], move: { item: T; from: number; to: number }, section: "active" | "completed") => Result;
  onDelete?: (task: T) => Result;
  /** Restores a deleted task when the person presses Undo. */
  onRestore?: (task: T) => Result;
  /** Return a message to reject a title. Defaults to requiring a non-empty title. */
  validateTitle?: (title: string) => string | null | undefined;
  disabled?: boolean;
  /** Animation in every part. Turning it off never removes an action. Reduced motion is always honored. */
  motion?: boolean;
  messages?: Partial<DailyTaskListMessages>;
  /** Where task menus are portalled. Defaults to document.body. */
  portalContainer?: HTMLElement | null;
  children?: ReactNode;
};

"use client";

import { type ReactNode } from "react";
import { useDailyTaskListContext, type DailyTask } from "./daily-task-list-state";
import { cn } from "@/lib/utils";
import { type RowOptions } from "./daily-task-list-actions";
import { InlineEdit, InlineEditPreview, InlineEditEditor, InlineEditInput, InlineEditError } from "@/components/ui/inline-edit";

/** A line across the title: drawn in while a task is being completed, and shown on completed tasks. */
export function Struck({ on, children }: { on: boolean; children: ReactNode }) {
  const { animated } = useDailyTaskListContext("DailyTaskList");
  return (
    <span
      className={cn(
        "relative inline-block max-w-full truncate align-bottom before:pointer-events-none before:absolute before:inset-x-0 before:top-1/2 before:h-px before:origin-left before:bg-current",
        on ? "text-muted-foreground before:scale-x-100" : "before:scale-x-0",
        animated && "transition-colors before:transition-transform before:duration-300 before:ease-out motion-reduce:transition-none motion-reduce:before:transition-none",
      )}
    >
      {children}
    </span>
  );
}

// One line of text in a 24px box, so a row's padding is the same above and below its content.
export const titleBox = "min-h-6 h-6";

export function TaskTitle({ task, options }: { task: DailyTask; options: RowOptions }) {
  const { rename, renamingId, setRenamingId, validate, disabled, animated, busy, striking, messages } = useDailyTaskListContext("DailyTaskList");
  if (!rename || task.done) {
    return (
      <span className={cn("flex min-w-0 items-center px-1", titleBox, options.classNames?.title)}>
        <Struck on={task.done}>{task.title}</Struck>
      </span>
    );
  }
  return (
    <InlineEdit
      label={messages.titleLabel}
      value={task.title}
      onSave={(title) => rename(task, title)}
      validate={validate}
      editing={renamingId === task.id}
      onEditingChange={(editing) => setRenamingId(editing ? task.id : null)}
      disabled={disabled || busy.has(task.id)}
      motion={animated}
      // Ghost: edit on top of the title with no buttons; Enter or leaving saves, Escape cancels.
      variant="ghost"
      className="min-w-0 flex-1"
    >
      {/* Not faded while busy: the strike already shows a completion in progress. */}
      <InlineEditPreview className={cn("w-full disabled:opacity-100", titleBox, options.classNames?.title)}>
        {(title) => <Struck on={striking.has(task.id)}>{title}</Struck>}
      </InlineEditPreview>
      <InlineEditEditor>
        <InlineEditInput className={cn(titleBox, options.classNames?.title)} />
      </InlineEditEditor>
      <InlineEditError className="px-1 text-xs" />
    </InlineEdit>
  );
}

